package modern.repository.sample;

import java.util.List;
import java.util.Optional;

/**
 * Mediates between the domain and the data-mapping layer using a
 * collection-like interface for accessing domain objects (Fowler, PoEAA).
 *
 * The business layer (UserService) depends only on THIS interface — it never
 * sees SQL, an ORM, a file path, or a network call. Any storage technology
 * can sit behind it as long as it implements these 4 methods.
 */
public interface IUserRepository {
    void save(User user);
    Optional<User> findById(int id);
    List<User> findAll();
    void deleteById(int id);
}

package modern.repository.sample;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * One concrete storage technology behind UserRepository — here, an in-memory
 * Map standing in for a real database. Swap this class for
 * JdbcUserRepository / MongoUserRepository / a fake-for-tests later, and
 * nothing in UserService changes, because UserService never named this
 * class — only the UserRepository interface.
 */
public class InMemoryUserRepository implements IUserRepository {
    private final Map<Integer, User> store = new LinkedHashMap<>();

    @Override
    public void save(User user) {
        store.put(user.getId(), user);
    }

    @Override
    public Optional<User> findById(int id) {
        return Optional.ofNullable(store.get(id));
    }

    @Override
    public List<User> findAll() {
        return new ArrayList<>(store.values());
    }

    @Override
    public void deleteById(int id) {
        store.remove(id);
    }
}

package modern.repository.sample;

public class Main {
    public static void main(String[] args) {
        // Only Main (the composition root) knows the concrete
        // InMemoryUserRepository exists — UserService only ever sees the
        // UserRepository interface.
        IUserRepository repository = new InMemoryUserRepository();
        UserService userService = new UserService(repository);

        userService.registerUser(1, "Shubhi");
        userService.registerUser(2, "Prateek");

        System.out.println("All users: " + userService.listUsers());
        System.out.println("Lookup id=1: " + userService.getUser(1));

        userService.removeUser(2);
        System.out.println("After removing id=2: " + userService.listUsers());
    }
}

package modern.repository.sample;

/**
 * Plain domain object — no persistence knowledge, no ORM annotations.
 * The Repository is what knows how a User gets stored/retrieved, not the User itself.
 */
public class User {
    private final int id;
    private final String name;

    public User(int id, String name) {
        this.id = id;
        this.name = name;
    }

    public int getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    @Override
    public String toString() {
        return "User{id=" + id + ", name='" + name + "'}";
    }
}

package modern.repository.sample;

import java.util.List;

/**
 * Business logic layer. Depends on the UserRepository INTERFACE — injected
 * via the constructor (this is Repository + Dependency Injection working
 * together, the way they show up in almost every real layered codebase).
 *
 * Nothing in this class would change if InMemoryUserRepository were replaced
 * by a real database-backed implementation.
 */
public class UserService {
    private final IUserRepository userRepository;

    public UserService(IUserRepository userRepository) {
        this.userRepository = userRepository;
    }

    public void registerUser(int id, String name) {
        userRepository.save(new User(id, name));
    }

    public User getUser(int id) {
        return userRepository.findById(id)
                .orElseThrow(() -> new IllegalArgumentException("No user with id " + id));
    }

    public List<User> listUsers() {
        return userRepository.findAll();
    }

    public void removeUser(int id) {
        userRepository.deleteById(id);
    }
}

